contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(newOwner != address(this));
        // caller (this contract) is the initial owner, so call must not revert
        c.transferOwnership(newOwner);
        address nowOwner = c.owner();
        assert(nowOwner == newOwner);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(newOwner != address(0));
        bool revertedOwned;
        try c.owned() { revertedOwned = false; } catch { revertedOwned = true; }
        bool revertedTransfer;
        try c.transferOwnership(newOwner) { revertedTransfer = false; } catch { revertedTransfer = true; }
        assert(revertedOwned && revertedTransfer && c.owner() == address(0));
    }
    receive() external payable {}
}
